// Olivia’s Birkdale Blitz Bus — Cloudflare Worker
// Serves the avocado-themed web page and Translink Route 255 realtime data.
const PAGE = "<!doctype html>\n<html lang=\"en-AU\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<meta name=\"theme-color\" content=\"#f6f9e9\">\n<meta name=\"description\" content=\"Olivia's Birkdale Blitz Bus: live Translink Route 255 school-run tracker.\">\n<title>Olivia's Birkdale Blitz Bus 🥑 — Live 255</title>\n<style>\n:root{color-scheme:light;--bg:#f6f9e9;--ink:#153e2c;--muted:#5e746a;--line:#d8e7cf;--pink:#ee386e;--pinkdark:#b9104a;--cream:#fffef7;--mint:#18814a;--amber:#a96800;--red:#be2347;--blue:#355a83}\n*{box-sizing:border-box}\nbody{margin:0;background:radial-gradient(ellipse 130% 30% at 0% 0%,#ffeedf 0,transparent 64%),radial-gradient(ellipse 100% 30% at 100% 15%,#d9f1c7,transparent 76%),var(--bg);color:var(--ink);font:16px/1.5 system-ui,-apple-system,'Segoe UI',Roboto,Arial,sans-serif}\n.shell{max-width:750px;margin:auto;padding:18px 16px 38px}\n.masthead{background:linear-gradient(130deg,#fff3dd 3%,#f8ffd9 52%,#dfedcc);border:2px solid #fff;border-radius:28px;padding:19px 19px 15px;position:relative;min-height:174px;box-shadow:0 8px 26px #4166381b;overflow:hidden}\n.masthead:before{content:'♡';font-size:90px;line-height:1;color:#f7a1bf55;position:absolute;right:6px;top:-25px;transform:rotate(15deg)}\n.titleBlock{position:relative;z-index:1;max-width:73%}\n.superTitle{font-size:13px;font-weight:900;letter-spacing:1.4px;text-transform:uppercase;color:#567c43}\n.nameLine{font-family:Georgia,'Times New Roman',serif;font-style:italic;font-weight:900;color:#ee4077;font-size:clamp(32px,7vw,52px);line-height:1.1;margin:7px 0 0;letter-spacing:-1.6px}\n.mainTitle{font-weight:950;letter-spacing:-1px;font-size:clamp(24px,5.1vw,37px);line-height:1.13;margin:0 0 9px;color:#185536}\n.subtitle{font-size:13px;font-weight:800;color:#416c4d}\n.topMascot{position:absolute;right:-15px;bottom:-18px;width:40%;max-width:215px;height:150px;object-fit:cover;object-position:52% 18%;border-radius:100px 0 0 12px;transform:rotate(-4deg);box-shadow:-4px 3px 25px #204d2a12}\n.routeRow{display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap;margin:15px 2px 0}\n.routeTag{background:#ffeb9f;border:1px solid #f6db7c;color:#3a3d18;border-radius:999px;padding:9px 13px;font-weight:900;font-size:14px}\n.chip{display:inline-flex;align-items:center;gap:7px;padding:8px 13px;background:#fff;border:1px solid #d2e8d1;border-radius:999px;white-space:nowrap;font-weight:950;font-size:12px;color:#7a673d;letter-spacing:.4px}\n.chip.ok{color:#087a43;background:#e5fae7}.chip.bad{color:#b31c48;background:#fff0f3}.chip.wait{color:#946a13;background:#fff8e6}\n.dot{width:8px;height:8px;border-radius:50%;background:currentColor}\n.schoolbanner{margin:14px 0 0;font-weight:800;font-size:13px;color:#466849;padding:8px 13px;border-radius:14px;background:#eaf7e2}\n.refreshArea{margin:16px 0 7px;text-align:center;position:sticky;top:8px;z-index:12}\n.refreshButton{width:100%;min-height:74px;border:none;border-radius:23px;display:flex;gap:16px;align-items:center;justify-content:center;cursor:pointer;background:linear-gradient(100deg,#fd3675,#e71d63);color:#fff;font-weight:950;letter-spacing:.4px;font-size:clamp(17px,4.2vw,23px);box-shadow:0 7px 0 #a41649,0 14px 25px #bd14534a;outline-offset:4px;padding:12px 15px;text-shadow:0 1px 1px #9b194866}\n.refreshButton svg{width:34px;height:34px;flex:none;stroke:#fff;stroke-width:2.5;fill:none;stroke-linecap:round;stroke-linejoin:round}\n.refreshButton:focus-visible{outline:4px solid #146641}.refreshButton:not(:disabled):active{transform:translateY(3px);box-shadow:0 4px 0 #a41649,0 8px 14px #bd14534a}.refreshButton:disabled{opacity:.78;cursor:progress}\n.refreshButton[data-loading=true] svg{animation:spin 1.4s linear infinite}@keyframes spin{to{transform:rotate(360deg)}}\n.refreshHelp{font-size:12px;font-weight:750;color:#5c6d54;margin:11px 0 0}.updated{font-weight:900;color:#315e42}\n.stopCard{background:#fffefb;border:1px solid var(--line);border-radius:21px;padding:18px 19px;margin:18px 0 0;box-shadow:0 8px 20px #264b1b0d}\n.stopOver{font-size:12px;font-weight:950;letter-spacing:1px;text-transform:uppercase;color:#678656;margin-bottom:5px}\n.label{display:inline;font-weight:800}.stopName{font-weight:900;font-size:clamp(19px,5.3vw,27px);line-height:1.2;margin:4px 0 6px;color:#123f2c}.secondary{color:var(--muted);font-size:13px}.routeDirections{font-weight:750}.miniBus{color:#9a6500;font-weight:900}\n.hero{background:linear-gradient(135deg,#f8ffea 0%,#f3fedf 55%,#e0f2c7 100%);border:2px solid #fff;border-radius:28px;box-shadow:0 9px 20px #304f2414;margin-top:18px;padding:20px 20px 18px;overflow:hidden;position:relative;min-height:255px}\n.heroTop{display:flex;align-items:center;justify-content:space-between;gap:10px;position:relative;z-index:1}.minibar{font-size:13px;color:#225e3b;font-weight:950;letter-spacing:.3px}\n.heroMain{display:flex;align-items:center;justify-content:space-between;min-height:138px;gap:4px;position:relative}.heroNumbers{min-width:0;position:relative;z-index:2}\n.bigclock{color:#134e30;font-weight:1000;font-size:clamp(54px,12vw,86px);letter-spacing:-3px;line-height:1.05;margin:14px 0 3px;white-space:nowrap}\n.heroHint{font-size:14px;font-weight:750;color:#536e51;max-width:270px}\n.heroAvo{display:block;width:36%;max-width:205px;min-width:103px;aspect-ratio:1;object-fit:cover;object-position:center;border-radius:27px;box-shadow:0 6px 15px #3f763020;transform:rotate(3deg);border:4px solid #fff5;align-self:center}\n.delayline{display:inline-block;font-weight:950;font-size:16px;color:#466657;margin:8px 0 0;background:#ffffffc7;border-radius:12px;padding:5px 10px}\n.delayline.late{color:var(--red);background:#ffe7eb}.delayline.good{color:#057444;background:#e0f7d9}.delayline.early{color:#8b6403;background:#fff1c4}\n.heroFoot{border-top:1px dashed #b8d4a6;margin-top:15px;padding-top:13px;display:flex;gap:20px;justify-content:space-between;flex-wrap:wrap}.dataLabel{font-size:12px;color:#5f755c;font-weight:750}.dataValue{font-size:21px;font-weight:950;margin-top:2px}\nh2{margin:24px 0 12px;font-size:20px;font-weight:950}.upcoming{display:grid;gap:9px}.trip{background:#fffefb;border:1px solid #dbe8cf;border-radius:18px;display:flex;align-items:center;justify-content:space-between;gap:12px;padding:15px 17px;box-shadow:0 4px 9px #33552a0b}\n.time{font-size:22px;font-weight:950;color:#234a32}.tripSub{font-size:12px;color:var(--muted)}.status{font-weight:950;font-size:13px;text-align:right;max-width:150px}.status.good{color:#097741}.status.early{color:var(--amber)}.status.late{color:var(--red)}.status.neutral{color:var(--muted)}\n.notice{margin-top:15px;border-radius:16px;padding:14px 16px;background:#fff7df;color:#554316;border:1px solid #f4dca9;font-weight:650;font-size:13px}.notice.error{background:#fff0f0;color:#8b2440;border-color:#f5b5c5}.notice.good{background:#e4f8e8}\n.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:19px}.btn{display:inline-flex;align-items:center;justify-content:center;text-decoration:none;background:#edfae7;color:#164a33;border:1px solid #b6deb2;padding:13px 17px;border-radius:15px;font-size:14px;font-weight:900;cursor:pointer}.btn.primary{background:#267a46;color:#fff;border-color:#267a46}.btn:hover{filter:brightness(.98)}button,input{font:inherit}button:disabled{opacity:.7}\n.settings{background:#fffefb;border:1px solid var(--line);padding:17px 19px;margin-top:22px;border-radius:18px}details summary{cursor:pointer;font-weight:900}details[open] summary{margin-bottom:17px}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}label{display:block;color:#416249;font-weight:750;font-size:13px;margin:13px 0 5px}input{width:100%;border:1px solid #adc6a7;border-radius:12px;background:#fff;color:#163b28;padding:12px 12px;font-size:16px}input:focus{outline:3px solid #9bdab3}\na{color:#136d44}.footer{font-size:12px;color:#55705c;line-height:1.6;padding:25px 4px 7px}.bye{font-weight:950;color:#e03776;font-size:16px;margin-bottom:6px}.hidden{display:none!important}\n@media(max-width:500px){.shell{padding:13px 12px 26px}.masthead{min-height:166px;padding:17px 16px 12px}.titleBlock{max-width:77%}.nameLine{font-size:35px}.mainTitle{font-size:27px}.topMascot{width:34%;max-width:150px;height:140px;right:-16px}.refreshButton{min-height:74px;padding:12px 10px;gap:8px}.refreshButton svg{width:28px;height:28px}.hero{padding:17px 15px}.heroAvo{width:33%;min-width:100px}.heroTop{align-items:flex-start}.heroTop .secondary{font-size:11px;max-width:105px;text-align:right}.heroFoot{gap:16px}}\n@media(max-width:370px){.nameLine{font-size:31px}.mainTitle{font-size:24px}.topMascot{max-width:120px}.two{grid-template-columns:1fr}.heroAvo{min-width:90px}.bigclock{font-size:clamp(43px,11vw,59px)}.refreshButton{font-size:16px}.routeTag{font-size:12px}}\n@media(prefers-reduced-motion:reduce){.refreshButton[data-loading=true] svg{animation:none}}\n</style>\n</head>\n<body>\n<div class=\"shell\">\n <header class=\"masthead\">\n  <div class=\"titleBlock\"><div class=\"superTitle\">🥑 Olivia's happy little bus tracker</div><div class=\"nameLine\">Olivia's</div><h1 class=\"mainTitle\">Birkdale Blitz Bus</h1><div class=\"subtitle\">A cuddly avo adventure to school! ♡</div></div>\n  <img class=\"topMascot\" src=\"data:image/webp;base64,\" alt=\"Smiling cuddly avocado mascot\" width=\"182\" height=\"162\">\n </header>\n <div class=\"routeRow\"><span class=\"routeTag\">🚌 ROUTE 255 · TO BIRKDALE</span><span id=\"feedState\" class=\"chip wait\"><span class=\"dot\"></span><span id=\"feedText\">CONNECTING</span></span></div>\n <div class=\"schoolbanner\" id=\"schoolBanner\">School run · Weekdays 6:00–9:30 am · Towards Birkdale</div>\n <div class=\"refreshArea\">\n  <button type=\"button\" id=\"refresh\" class=\"refreshButton\" aria-label=\"Refresh the latest live Bus 255 times\" data-loading=\"false\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 11a9 9 0 0 0-15.4-6.4L3 7\"/><path d=\"M3 2v5h5\"/><path d=\"M3 13a9 9 0 0 0 15.4 6.4L21 17\"/><path d=\"M16 17h5v5\"/></svg><span id=\"refreshLabel\">REFRESH LIVE BUS TIMES</span></button>\n  <div class=\"refreshHelp\">👆 Tap anytime to check the latest departure · <span class=\"updated\" id=\"lastUpdated\">Not updated yet</span></div>\n </div>\n <section class=\"stopCard\" aria-label=\"Bus stop\">\n  <div class=\"stopOver\">📍 Olivia's bus stop · Stop <span id=\"stopNumber\">313567</span></div>\n  <h2 class=\"stopName\" id=\"stopTitle\">McDonald Rd at Montgomery Drive</h2>\n  <div class=\"secondary routeDirections\" id=\"directionLabel\">Towards Birkdale · school morning route</div>\n </section>\n <section class=\"hero\" aria-live=\"polite\" aria-label=\"Next bus\">\n  <div class=\"heroTop\"><span class=\"minibar\">✨ NEXT BUS <span class=\"miniBus\">255</span></span><span class=\"secondary\">Towards Birkdale</span></div>\n  <div class=\"heroMain\">\n   <div class=\"heroNumbers\"><div class=\"bigclock\" id=\"heroClock\">—</div><div class=\"heroHint\" id=\"heroHint\">Connecting to real-time departures…</div><div class=\"delayline\" id=\"heroStatus\">Awaiting live data</div></div>\n   <img class=\"heroAvo\" src=\"data:image/webp;base64,\" width=\"180\" height=\"180\" alt=\"Happy plush avocado gives Olivia a cheer\">\n  </div>\n  <div class=\"heroFoot\"><div><div class=\"dataLabel\">Expected departure</div><div class=\"dataValue\" id=\"predicted\">—</div></div><div><div class=\"dataLabel\">Scheduled departure</div><div class=\"dataValue\" id=\"scheduled\">—</div></div></div>\n </section>\n <div class=\"notice hidden\" id=\"notice\" role=\"status\"></div>\n <h2 id=\"upcomingTitle\">🚌 Upcoming Route 255 departures</h2>\n <div id=\"upcoming\" class=\"upcoming\"><div class=\"trip\"><div class=\"secondary\">Checking live bus information…</div></div></div>\n <div class=\"actions\"><a class=\"btn\" id=\"official\" href=\"https://jp.translink.com.au/plan-your-journey/stops/313567\" target=\"_blank\" rel=\"noopener\">🗺️ Open official live stop ↗</a></div>\n <div class=\"settings\"><details id=\"settings\"><summary>⚙️ Settings — change bus stop or live-feed connection</summary>\n   <div class=\"two\"><div><label for=\"stopId\">Translink stop ID</label><input id=\"stopId\" inputmode=\"numeric\" maxlength=\"8\" value=\"313567\" placeholder=\"e.g. 313567\"></div><div><label for=\"direction\">Bus direction / description</label><input id=\"direction\" value=\"Towards Birkdale · school morning route\"></div></div>\n   <label for=\"stopName\">Your stop's name</label><input id=\"stopName\" value=\"McDonald Rd at Montgomery Drive\">\n   <label for=\"apiBase\">Cloudflare Worker URL (for GitHub Pages)</label><input id=\"apiBase\" type=\"url\" placeholder=\"https://bus255-tracker.gztvz100.workers.dev\" autocomplete=\"url\">\n   <div class=\"actions\"><button id=\"save\" class=\"btn primary\" type=\"button\">💚 Save settings</button></div>\n   <p class=\"secondary\">Make sure the stop ID matches the direction Olivia boards. The stop ID controls live departures; the description only changes this page's label. On GitHub Pages the known Cloudflare Worker is prefilled but can be changed. Find your stop using <a href=\"https://translink.com.au/plan-your-journey/real-time\" target=\"_blank\" rel=\"noopener\">Translink's stop search</a>.</p>\n  </details></div>\n <footer class=\"footer\"><div class=\"bye\">💗 You've got this, Olivia! 🥑</div>Live predictions are provided by Queensland Translink (GTFS Realtime, CC BY 4.0). Predictions change and may be missing; check the <a id=\"officialFooter\" href=\"https://jp.translink.com.au/plan-your-journey/stops/313567\" target=\"_blank\" rel=\"noopener\">official stop information</a> before travelling. <a href=\"https://creativecommons.org/licenses/by/4.0/\" target=\"_blank\" rel=\"noopener\">Licence</a>. Automatically checks every 30 seconds while open. Times shown in Brisbane time (AEST).</footer>\n</div>\n<script>\n(()=>{'use strict';\n const $=id=>document.getElementById(id);\n const STORAGE_KEY='route255.schoolrun.v1';\n const defaults={stopId:'313567',stopName:'McDonald Rd at Montgomery Drive',direction:'Towards Birkdale · school morning route',apiBase:(location.hostname.endsWith('github.io')||location.protocol==='file:')?'https://bus255-tracker.gztvz100.workers.dev':''};\n let cfg={...defaults},data=null,loading=false,lastOK=0,problem='';\n try{cfg={...cfg,...JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}')}}catch{}\n for(const key of ['stopId','stopName','direction','apiBase'])$(key).value=cfg[key]||'';\n function formatTime(seconds){if(!Number.isFinite(seconds))return '—';return new Intl.DateTimeFormat('en-AU',{timeZone:'Australia/Brisbane',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(seconds*1000))}\n function timeLeft(t){const s=t-Date.now()/1000;if(s< -75)return 'Departed';if(s<30)return 'Due now';if(s<90)return '1 min';return Math.ceil(s/60)+' min'}\n function statusOf(t){if(t.cancelled)return {text:'Cancelled',kind:'late'};if(t.skipped)return {text:'Stop skipped',kind:'late'};if(!Number.isFinite(t.delay))return {text:'Live prediction · delay unknown',kind:'neutral'};const n=Math.round(Math.abs(t.delay)/60);if(Math.abs(t.delay)<60)return {text:'On time',kind:'good'};if(t.delay>0)return{text:n+' min late',kind:'late'};return{text:n+' min early',kind:'early'}}\n function setFeed(text,state){$('feedText').textContent=text;$('feedState').className='chip '+state}\n function setNotice(text,error=false){$('notice').textContent=text;$('notice').className='notice'+(error?' error':'')+(text?'':' hidden')}\n function resetDisplay(msg){$('heroClock').textContent='—';$('heroHint').textContent=msg;$('heroStatus').textContent='No live prediction';$('heroStatus').className='delayline';$('predicted').textContent='—';$('scheduled').textContent='—';$('upcoming').innerHTML='';const el=document.createElement('div');el.className='trip';el.textContent=msg;$('upcoming').append(el)}\n function isSchoolMorning(){const p=new Intl.DateTimeFormat('en-GB',{timeZone:'Australia/Brisbane',weekday:'short',hour:'2-digit',minute:'2-digit',hour12:false}).formatToParts(new Date());const obj=Object.fromEntries(p.map(x=>[x.type,x.value]));const min=Number(obj.hour)*60+Number(obj.minute);return ['Mon','Tue','Wed','Thu','Fri'].includes(obj.weekday)&&min>=360&&min<570}\n function render(){\n  const morning=isSchoolMorning();$('schoolBanner').textContent=morning?'SCHOOL MORNING · Route 255 towards Birkdale · Live now':'SCHOOL RUN · Route 255 towards Birkdale · Weekdays 6:00–9:30 am';\n  $('upcomingTitle').textContent=morning?'Morning departures towards Birkdale':'Upcoming 255 services towards Birkdale';\n  $('stopNumber').textContent=cfg.stopId;$('stopTitle').textContent=cfg.stopName||'Bus stop '+cfg.stopId;$('directionLabel').textContent=cfg.direction||'Route 255';\n  const official='https://jp.translink.com.au/plan-your-journey/stops/'+encodeURIComponent(cfg.stopId);$('official').href=official;$('officialFooter').href=official;\n  if(!data){resetDisplay(problem?'No live times available right now. Tap refresh or open the official stop.':'Checking real-time predictions…');return}\n  const now=Date.now()/1000,stale=Number.isFinite(data.feedTimestamp)&&data.feedTimestamp>0&&now-data.feedTimestamp>300;\n  const feedAge=Number.isFinite(data.feedTimestamp)&&data.feedTimestamp>0?Math.max(0,Math.round((now-data.feedTimestamp)/60)):null;\n  $('lastUpdated').textContent=lastOK?('Checked '+new Intl.DateTimeFormat('en-AU',{timeZone:'Australia/Brisbane',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(lastOK))):'Not updated';\n  if(stale){setFeed('STALE','bad');setNotice('The Translink feed is '+feedAge+' minutes old. Its predictions might no longer be reliable; check the official stop page.',true)}\n  else if(problem){setFeed('OFFLINE','bad');setNotice(problem+'. Last retrieved results may be out of date.',true)}\n  else{setFeed('LIVE','ok');setNotice(data.trips.length?'':'No live route 255 predictions for this stop right now. This does not mean the bus has been cancelled. Check the official timetable or try again nearer departure time.')}\n  const all=data.trips.filter(x=>Number.isFinite(x.expected)?x.expected>now-90&&x.expected<now+4*3600:true).sort((a,b)=>(a.expected??Number.MAX_SAFE_INTEGER)-(b.expected??Number.MAX_SAFE_INTEGER)).slice(0,6);\n  if(!all.length){resetDisplay(isSchoolMorning()?'No live morning predictions at this stop':'No upcoming predictions right now · Check again on a school morning');return}\n  const next=all[0],stat=statusOf(next);\n  $('heroClock').textContent=Number.isFinite(next.expected)?timeLeft(next.expected):'—';\n  $('heroHint').textContent=Number.isFinite(next.expected)?'Until the predicted departure':'This service has no predicted departure time';\n  $('heroStatus').textContent=stat.text;$('heroStatus').className='delayline '+stat.kind;\n  $('predicted').textContent=formatTime(next.expected);$('scheduled').textContent=formatTime(next.scheduled);\n  $('upcoming').replaceChildren();\n  for(const t of all){const e=document.createElement('div');e.className='trip';const left=document.createElement('div');const f=document.createElement('div');f.className='time';f.textContent=Number.isFinite(t.expected)?formatTime(t.expected):'Time unavailable';const sub=document.createElement('div');sub.className='tripSub';sub.textContent='Due '+(Number.isFinite(t.expected)?timeLeft(t.expected):'unavailable')+(Number.isFinite(t.scheduled)?' · Scheduled '+formatTime(t.scheduled):'');left.append(f,sub);const right=document.createElement('div');const status=statusOf(t);right.className='status '+status.kind;right.textContent=status.text;e.append(left,right);$('upcoming').append(e)}\n }\n async function refresh(){if(loading)return;loading=true;$('refresh').disabled=true;$('refresh').dataset.loading='true';$('refreshLabel').textContent='CHECKING LIVE TIMES…';\n  const base=cfg.apiBase.trim().replace(/\\/+$/,'');const endpoint=(base||'')+'/api/arrivals?stop='+encodeURIComponent(cfg.stopId);\n  if(!base&&(location.protocol==='file:'||location.hostname.endsWith('github.io'))){\n    data=null;problem='To show live bus times, deploy the companion Cloudflare Worker and paste its address into Settings. The school-route dashboard is ready, but this page cannot retrieve live data until connected.';setFeed('SETUP NEEDED','wait');setNotice(problem,true);render();loading=false;$('refresh').disabled=false;$('refresh').dataset.loading='false';$('refreshLabel').textContent='REFRESH LIVE BUS TIMES';return;\n  }\n  try{const controller=new AbortController();const timeout=setTimeout(()=>controller.abort(),14000);let r;try{r=await fetch(endpoint,{cache:'no-store',signal:controller.signal})}finally{clearTimeout(timeout)}\n    if(!r.ok)throw Error('Live feed returned HTTP '+r.status);const res=await r.json();if(!res||!Array.isArray(res.trips))throw Error('Unexpected data format');data=res;lastOK=Date.now();problem='';render();\n  }catch(err){problem='Unable to refresh Translink data ('+(err.name==='AbortError'?'request timed out':err.message)+')';setFeed('OFFLINE','bad');setNotice(problem+'. Check your connection or the Worker setup, or use the official stop page.',true);render()}\n  finally{loading=false;$('refresh').disabled=false;$('refresh').dataset.loading='false';$('refreshLabel').textContent='REFRESH LIVE BUS TIMES'}\n }\n $('refresh').addEventListener('click',refresh);\n $('save').addEventListener('click',()=>{const stopId=$('stopId').value.trim();if(!/^\\d{4,8}$/.test(stopId)){alert('Enter the 4–8 digit Translink stop ID.');return}cfg={stopId,stopName:$('stopName').value.trim(),direction:$('direction').value.trim(),apiBase:$('apiBase').value.trim()};try{localStorage.setItem(STORAGE_KEY,JSON.stringify(cfg))}catch{}data=null;problem='';$('settings').open=false;setFeed('CONNECTING','wait');render();refresh()});\n window.setInterval(()=>{if(data)render()},1000);\n window.setInterval(()=>{if(document.visibilityState!=='hidden')refresh()},30000);\n document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&Date.now()-lastOK>20000)refresh()});\n render();refresh();\n})();\n</script>\n</body>\n</html>\n";
const FEED = 'https://gtfsrt.api.translink.com.au/api/realtime/SEQ/TripUpdates/Bus';
const decoder = new TextDecoder();

function fields(bytes, visit) {
  let p=0;
  function varint(){let num=0n,bit=0n;for(let k=0;k<10;k++){if(p>=bytes.length)throw new Error('Truncated protobuf');const byte=bytes[p++];num|=BigInt(byte&127)<<bit;if(!(byte&128))return num;bit+=7n}throw new Error('Invalid varint')}
  while(p<bytes.length){const tag=Number(varint());const id=tag>>>3;const wire=tag&7;if(id===0)throw new Error('Invalid protobuf field');
    if(wire===0){visit(id,wire,varint())}
    else if(wire===2){const size=Number(varint());if(size<0||p+size>bytes.length)throw new Error('Truncated protobuf bytes');const part=bytes.subarray(p,p+size);p+=size;visit(id,wire,part)}
    else if(wire===1){p+=8;if(p>bytes.length)throw new Error('Truncated fixed64')}
    else if(wire===5){p+=4;if(p>bytes.length)throw new Error('Truncated fixed32')}
    else throw new Error('Unsupported protobuf wire type: '+wire);
  }
}
function string(b){return decoder.decode(b)}
function event(b){const x={};fields(b,(id,w,v)=>{if(id===1&&w===0)x.delay=Number(BigInt.asIntN(32,v));if(id===2&&w===0)x.time=Number(v)});return x}
function stopTime(b,idWanted){const s={};fields(b,(id,w,v)=>{if(id===2&&w===2)s.arrival=event(v);if(id===3&&w===2)s.departure=event(v);if(id===4&&w===2)s.stopId=string(v);if(id===5&&w===0)s.rel=Number(v)});return s.stopId===idWanted?s:null}
function tripDescriptor(b){const t={};fields(b,(id,w,v)=>{if(id===1&&w===2)t.tripId=string(v);if(id===5&&w===2)t.routeId=string(v);if(id===4&&w===0)t.relationship=Number(v)});return t}
function tripUpdate(b,stopId){let trip={},pendingStops=[],tripDelay=null,stamp=null;
  // First read the route. Only decode individual stop predictions for route 255.
  fields(b,(id,w,v)=>{if(id===1&&w===2)trip=tripDescriptor(v);if(id===2&&w===2)pendingStops.push(v);if(id===4&&w===0)stamp=Number(v);if(id===5&&w===0)tripDelay=Number(BigInt.asIntN(32,v))});
  if(!/^255(?:-|$)/.test(trip.routeId||''))return null;
  let stop=null;for(const v of pendingStops){const match=stopTime(v,stopId);if(match){stop=match;break}}
  if(!stop)return null;
  const et=stop.departure||stop.arrival||{};
  const delay=Number.isFinite(et.delay)?et.delay:Number.isFinite(tripDelay)?tripDelay:null;
  const expected=Number.isFinite(et.time)?et.time:null;
  return {tripId:trip.tripId||'',expected,scheduled:expected!==null&&delay!==null?expected-delay:null,delay,skipped:stop.rel===1,cancelled:trip.relationship===3,stamp};
}
function parseFeed(buffer,stopId){const bytes=new Uint8Array(buffer);let feedTimestamp=null;const trips=[];
  fields(bytes,(id,w,v)=>{
    if(id===1&&w===2)fields(v,(field,wire,val)=>{if(field===3&&wire===0)feedTimestamp=Number(val)});
    if(id===2&&w===2)fields(v,(field,wire,val)=>{if(field===3&&wire===2){const trip=tripUpdate(val,stopId);if(trip)trips.push(trip)}});
  });
  return{route:'255',stopId,feedTimestamp,trips};
}
const cors={'access-control-allow-origin':'*','access-control-allow-methods':'GET,OPTIONS','access-control-allow-headers':'Content-Type'};
function json(data,status=200){return new Response(JSON.stringify(data),{status,headers:{...cors,'content-type':'application/json; charset=utf-8','cache-control':'no-store'}})}
export default {
  async fetch(request){
    const url=new URL(request.url);
    if(request.method==='OPTIONS')return new Response(null,{status:204,headers:cors});
    if(request.method!=='GET')return json({error:'Method not allowed'},405);
    if(url.pathname==='/api/arrivals'){
      const stop=url.searchParams.get('stop')||'313567';
      if(!/^\d{4,8}$/.test(stop))return json({error:'Invalid stop ID'},400);
      try{
        const res=await fetch(FEED,{cf:{cacheTtl:20,cacheEverything:true},headers:{accept:'application/x-protobuf'}});
        if(!res.ok)throw new Error('Translink returned HTTP '+res.status);
        if(res.headers.get('content-length')&&Number(res.headers.get('content-length'))>25000000)throw new Error('Feed is unexpectedly large');
        const data=parseFeed(await res.arrayBuffer(),stop);
        return json(data);
      }catch(err){return json({error:'Could not read Translink live feed',detail:String(err?.message||err)},502)}
    }
    if(url.pathname==='/'||url.pathname==='/index.html')return new Response(PAGE,{headers:{'content-type':'text/html; charset=utf-8','cache-control':'public, max-age=60','x-content-type-options':'nosniff'}});
    return new Response('Not found',{status:404});
  }
};
